using System;using Newtonsoft.Json.Linq;using SarmatVisionHold.KestrelClient.Models;
namespace SarmatVisionHold.KestrelClient.Networking { public sealed class TelemetryMessageParser {
 public bool TryParse(string json,out KestrelTelemetry t,out string error){t=null;error=null;try{var j=JObject.Parse(json);if((string)j["type"]!="telemetry"){error="Not a telemetry message";return false;}if((int?)j["protocolVersion"]!=1){error="Unsupported telemetry protocolVersion";return false;}Guid id;if(!Guid.TryParse((string)j["sessionId"],out id)){error="Invalid telemetry sessionId";return false;}t=new KestrelTelemetry{ProtocolVersion=1,SessionId=id,FrameNumber=ReqUInt(j,"frameNumber"),TimestampUs=ReqULong(j,"timestampUs"),SimulationTimeSeconds=Req(j,"simulationTimeSeconds"),Position=Vec(j["position"],true),VelocityWorld=Vec(j["velocityWorld"],true),VelocityBody=Vec(j["velocityBody"],true),AngularRateBody=Vec(j["angularRateBody"],true),WindWorld=Vec(j["windWorld"],true),Attitude=Att(j["attitude"]),Camera=Cam(j["camera"]),State=State(j["state"]),Input=Input(j["input"]),PhysicsTick=OptLong(j,"physicsTick"),RenderFrame=OptLong(j,"renderFrame"),Seed=(int)OptLong(j,"seed"),CaptureFps=Opt(j,"captureFps"),TotalDroppedFrames=OptLong(j,"totalDroppedFrames"),ReceivedUtc=DateTime.UtcNow};return true;}catch(Exception e){t=null;error="Invalid telemetry: "+e.Message;return false;}}
 static double Req(JToken j,string n){var v=j?[n];if(v==null)throw new FormatException("Missing "+n);return Finite((double)v,n);}static double Opt(JToken j,string n)=>j?[n]==null?0:Finite((double)j[n],n);static long OptLong(JToken j,string n)=>j?[n]==null?0:(long)j[n];static uint ReqUInt(JToken j,string n){var v=(long?)j?[n]??throw new FormatException("Missing "+n);if(v<0||v>uint.MaxValue)throw new FormatException(n+" out of range");return (uint)v;}static ulong ReqULong(JToken j,string n){var v=j?[n]??throw new FormatException("Missing "+n);return v.Value<ulong>();}static double Finite(double v,string n){if(double.IsNaN(v)||double.IsInfinity(v))throw new FormatException(n+" is not finite");return v;}
 static Vector3Data Vec(JToken j,bool required){if(j==null){if(required)throw new FormatException("Missing vector");return new Vector3Data();}return new Vector3Data{X=Req(j,"x"),Y=Req(j,"y"),Z=Req(j,"z")};}static AttitudeData Att(JToken j)=>new AttitudeData{RollRad=Req(j,"rollRad"),PitchRad=Req(j,"pitchRad"),YawRad=Req(j,"yawRad")};static CameraData Cam(JToken j)=>new CameraData{Width=(int)Req(j,"width"),Height=(int)Req(j,"height"),FovDegrees=Req(j,"fovDegrees"),MountRollRad=Req(j,"mountRollRad"),MountPitchRad=Req(j,"mountPitchRad"),MountYawRad=Req(j,"mountYawRad")};static StateData State(JToken j)=>new StateData{Paused=(bool?)j?["paused"]??false,Crashed=(bool?)j?["crashed"]??false,OnGround=(bool?)j?["onGround"]??false};static InputData Input(JToken j){var a=j?["axes"];return new InputData{Axes=new AxesData{Roll=Opt(a,"roll"),Pitch=Opt(a,"pitch"),Yaw=Opt(a,"yaw"),Throttle=Opt(a,"throttle")}};}
 } }
